    "id": "09_root_cause_analysis",
    "name": "Root Cause Analysis (5 Whys)",
    "description": "Cadena causal secuencial de 5 porqués hasta la causa raíz.",
    "icon": "ingenieria",
    "category": "Ingeniería",
    "categorySlug": "ingenieria",
    "subcategory": "Calidad & Causa Raíz",
    "tier": "specialized",
